    super.build_phase(phase);
    ap_imp = new("ap_imp", this);
  endfunction

  virtual function void write_mon(counter_seq_item item);
  // Don't model anything while we're sampling X's
  if (item.dout === 4'hx || item.dout === 4'hz) begin
    `uvm_info("SCB", "Skipping X/Z sample (pre-reset settling)", UVM_HIGH)
    return;
  end

  // Wait until we've seen a reset land before we trust our model
  if (!initialized) begin
    if (item.rst) begin
      expected_dout = 4'h0;
      initialized   = 1;
      `uvm_info("SCB", "Scoreboard initialized via observed reset", UVM_LOW)
