    return;  // no compare yet — we're still aligning
  end

  // Step 1: compare current dout against value predicted last cycle
  num_checks++;
  if (item.dout !== expected_dout) begin
    num_errors++;
    `uvm_error("SCB",
      $sformatf("MISMATCH: expected dout=0x%0h, got dout=0x%0h (rst=%0b up=%0b)",
                expected_dout, item.dout, item.rst, item.up))
  end
  else begin
    `uvm_info("SCB",
      $sformatf("MATCH: dout=0x%0h (rst=%0b up=%0b)",
                item.dout, item.rst, item.up),
      UVM_HIGH)
  end

  // Step 2: predict next cycle's dout from this cycle's inputs
  if (item.rst)
    expected_dout = 4'h0;
  else if (item.up)
    expected_dout = expected_dout + 4'd1;
  else
    expected_dout = expected_dout - 4'd1;
endfunction

