      `uvm_error("SCB", $sformatf("TEST FAILED with %0d mismatches", num_errors))
    else if (num_checks == 0)
      `uvm_warning("SCB", "No transactions were checked")
    else
      `uvm_info("SCB", "TEST PASSED", UVM_LOW)
